MAGIC = {
    b'MZ': 'PE executable',
    b'\x7fELF': 'ELF executable',
    b'%PDF': 'PDF',
    b'PK\x03\x04': 'ZIP container',
    b'\x89PNG': 'PNG image',
}

def identify(header):
    for magic, name in MAGIC.items():
        if header.startswith(magic):
            return name
    return 'unknown'

for h in (b'MZ\x90\x00', b'\x7fELF\x02\x01', b'PK\x03\x04\x14\x00', b'hello'):
    print(identify(h))

from datetime import datetime, timedelta, timezone

def filetime_to_utc(ft):
    epoch = datetime(1601, 1, 1, tzinfo=timezone.utc)
    return epoch + timedelta(microseconds=ft // 10)

print(filetime_to_utc(116444736000000000).isoformat())
print(filetime_to_utc(133801632000000000).isoformat())
